program='''def transform(grid):
    # Remove the six-row color key and retain the drawing canvas.
    out = [row[:] for row in grid[6:]]
    h, w = len(out), len(out[0])
    # Extend each colored rectangle toward the two nearest outer edges.
    # The central azure rectangle instead extends in all four directions.
    from collections import Counter
    bg = Counter(x for row in out for x in row).most_common(1)[0][0]
    rects = {}
    for r, row in enumerate(out):
        for c, color in enumerate(row):
            if color != bg:
                if color not in rects:
                    rects[color] = [r, r, c, c]
                else:
                    q = rects[color]
                    q[0] = min(q[0], r); q[1] = max(q[1], r)
                    q[2] = min(q[2], c); q[3] = max(q[3], c)
    for color, (r0, r1, c0, c1) in rects.items():
        if color == 8:
            for r in range(h):
                for c in range(c0, c1 + 1): out[r][c] = color
            for r in range(r0, r1 + 1):
                for c in range(w): out[r][c] = color
        else:
            # Horizontal ray points to the closer side; the vertical ray is
            # down for a left-side rectangle and up for a right-side one.
            if c0 + c1 < w - 1:
                for r in range(r0, r1 + 1):
                    for c in range(0, c0): out[r][c] = color
                for r in range(r1 + 1, h):
                    for c in range(c0, c1 + 1): out[r][c] = color
